export function modelPart(id,kind,position=[0,0,0],scale=[1,1,1],color='#999999',extra={}){return {id,name:id,geometry:{kind},position,rotation:[0,0,0],scale,material:{color},...extra};}
export function modelBeam(id,a,b,r=.025,color='#777777'){const v=b.map((x,i)=>x-a[i]),L=Math.hypot(...v)||.001;return modelPart(id,'cylinder',a.map((x,i)=>(x+b[i])/2),[r*2,L,r*2],color,{rotation:[Math.asin(v[2]/L)*180/Math.PI,0,Math.atan2(-v[0],v[1])*180/Math.PI]});}
export function helmetModel(){return {id:'helmet',name:'Salvage helmet',children:[modelPart('dome','hemisphere',[0,0,0],[1,.75,1.1],'#77764f'),modelPart('brim','torus',[0,0,0],[1.16,1.3,.8],'#686741',{rotation:[90,0,0],geometry:{kind:'torus',segments:24,tube:.035}})]};}
export function bicycleModel(){const children=[];for(const x of [-1.15,1.15]){const wheel={id:x<0?'rear-wheel':'front-wheel',position:[x,1,0],rotation:[0,0,0],animation:{spin:[0,0,100]},children:[modelPart('rim','torus',[0,0,0],[1.85,1.85,1.85],'#453d31',{geometry:{kind:'torus',segments:32,tube:.025}}),modelPart('tire','torus',[0,0,0],[1.95,1.95,1.95],'#272522',{geometry:{kind:'torus',segments:40,tube:.018}}),modelPart('hub','cylinder',[0,0,0],[.13,.2,.13],'#777777',{rotation:[90,0,0]})]};for(let i=0;i<32;i++){const a=i/32*Math.PI*2;wheel.children.push(modelBeam('spoke-'+i,[0,0,0],[Math.cos(a)*.92,Math.sin(a)*.92,0],.007,'#8b8981'));}children.push(wheel);}for(const [i,a,b]of [[0,[-1.15,1,0],[-.3,1.8,0]],[1,[-.3,1.8,0],[.1,.85,0]],[2,[.1,.85,0],[-1.15,1,0]],[3,[-.3,1.8,0],[.95,1.9,0]],[4,[.95,1.9,0],[.1,.85,0]],[5,[.95,1.9,0],[1.15,1,0]],[6,[-.3,1.8,0],[-.4,2.15,0]],[7,[.95,1.9,0],[.85,2.25,0]]])children.push(modelBeam('frame-'+i,a,b,.035,'#3b302a'));children.push(modelPart('seat','box',[-.45,2.16,0],[.45,.08,.25],'#342923'),modelBeam('handlebar',[.85,2.25,-.38],[.85,2.25,.38],.025,'#665b4b'));return {id:'bicycle',name:'Wheel-driven bicycle assembly',children};}
export function bipedModel(){const body=modelPart('coat','box',[0,1.65,0],[.62,.88,.32],'#383a3b'),head=modelPart('head','sphere',[0,2.35,0],[.35,.43,.34],'#8b8680');const children=[body,head];for(const side of [-1,1]){children.push({id:'leg-'+side,position:[side*.18,1.25,0],animation:{swing:{axis:0,rate:1,amplitude:26,phase:side<0?Math.PI:0}},children:[modelPart('thigh','box',[0,-.28,0],[.2,.6,.22],'#333537'),{id:'knee',position:[0,-.57,0],animation:{swing:{axis:0,rate:1,amplitude:20,phase:side<0?Math.PI+.7:.7}},children:[modelPart('shin','box',[0,-.25,0],[.18,.53,.2],'#2c2e30'),modelPart('boot','box',[0,-.53,.11],[.22,.17,.44],'#202123')]}]});children.push({id:'arm-'+side,position:[side*.42,1.94,0],animation:{swing:{axis:0,rate:1,amplitude:15,phase:side<0?0:Math.PI}},children:[modelPart('sleeve','box',[0,-.38,0],[.18,.78,.22],'#393b3d')]});}return {id:'biped',name:'Articulated blockout biped',children};}
export function ruinModel(){return {id:'ruin',name:'Editable ruined building blockout',children:[modelPart('left-pier','box',[-1.2,1.5,0],[.5,3,.5],'#66686a'),modelPart('right-pier','box',[1.2,1.4,0],[.5,2.8,.5],'#707274'),modelPart('lintel','box',[0,2.6,0],[2.3,.4,.5],'#606265'),modelPart('lower-wall','extrusion',[0,.5,0],[1,1,1],'#77797a',{geometry:{kind:'extrusion',polygon:[[-1.4,0],[1.4,0],[1.4,.8],[.6,.65],[.2,1],[-.8,.7],[-1.4,1.2]],depth:.4}})]};}
export function createModelRecipe(kind='box'){let nodes;if(kind==='bicycle')nodes=[bicycleModel()];else if(kind==='helmet')nodes=[helmetModel()];else if(kind==='biped')nodes=[bipedModel()];else if(kind==='ruin')nodes=[ruinModel()];else nodes=[modelPart('object-1',kind)];const identify=(nodes,prefix='')=>{for(const n of nodes){n.id=prefix+n.id;if(n.children)identify(n.children,n.id+'/')}};identify(nodes);return {schema:'motion-model-scene-v1',camera:{position:kind==='bicycle'?[4,2.5,7]:[4,3,7],target:kind==='bicycle'?[0,1,0]:[0,.5,0],fov:42},lights:{ambient:.45,direction:[-.3,.8,.6],intensity:.65},nodes};}
export function createRuinedStreet(){const nodes=[modelPart('ground','heightfield',[0,-.16,-35],[38,125,1],'#777777',{rotation:[-90,0,0],geometry:{kind:'heightfield',columns:32,rows:64,amplitude:.035,repeatX:4,repeatY:12},material:{color:'#888888',textureSlot:'salvageGround'}}),modelPart('road','heightfield',[0,-.10,-26],[5.4,75,1],'#777777',{rotation:[-90,0,0],geometry:{kind:'heightfield',columns:12,rows:40,amplitude:.018,repeatX:1,repeatY:10},material:{color:'#777777',textureSlot:'salvageGround'}})];for(const side of [-1,1])for(let i=0;i<5;i++){const z=2-i*10+(side>0?2:0),h=[10,6.2,8.7,4.3,7.2][(i+(side>0?1:0))%5],x=side*(4.3+(i%3)*.9),yaw=side<0?83+i%3*4:-82-i%3*5;nodes.push(modelPart('facade-'+side+'-'+i,'plane',[x,h/2,z],[8+(i%2)*2,h,1],'#999999',{rotation:[0,yaw,side*(i%3-1)*2],geometry:{kind:'plane',columns:4,rows:4},material:{color:'#aaaaaa',textureSlot:'salvageFacade'}}));nodes.push(modelPart('wall-reveal-'+side+'-'+i,'box',[x+side*.4,h*.32,z-3],[.23,h*.64,.65],'#656565',{rotation:[0,side*8,0],material:{color:'#777777',textureSlot:'salvageFacade'}}));}for(let i=0;i<64;i++){const side=i%2?1:-1;nodes.push(modelPart('rubble-'+i,'box',[side*(2.7+(Math.sin(i*23)*.5+.5)*3),.06+(i%3)*.1,4-i*.78],[.3+(i%5)*.24,.15+(i%3)*.17,.35+(i%4)*.23],'#777777',{rotation:[i*17,i*31,i*7],material:{color:'#999999',textureSlot:'salvageGround'}}));}return {schema:'motion-model-scene-v1',camera:{position:[0,1.7,6],target:[0,2,-30],fov:58},lights:{ambient:.54,direction:[-.3,.8,.5],intensity:.46},nodes};}
